/** #7e7e7e */
@font-face {
    font-family: 'Roboto';
    src: url(data:application/octet-stream;base64,);
    font-weight: normal;
}

@font-face {
    font-family: 'Roboto';
    src: url(data:application/octet-stream;base64,);
    font-weight: bold;
}

.cvo-document .cvo-page {
    background-image: url(data:image/png;base64,);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    height: 100%;
    padding: initial;
    box-shadow: none;
    position: relative;
}

#cvo-body {
    position: relative;
    padding-bottom: 16px;
}

.cvo-document .cvo-subpage {
    padding: initial;
}

.navigation .nav-header .action .toggle {
    width: 12px;
    height: 12px;
    display: inline-block;
    background: red;
    border-radius: 10px;
    margin: 0 2px;
}

.navigation .nav-header .action {
    margin: auto;
    display: inline-block;
    margin-right: 30px;
}

.navigation .nav-header .action .toggle.close {
    background: #FF453A;
}

.navigation .nav-header .action .toggle.hide {
    background: #FF9F0A;
}

.navigation .nav-header .action .toggle.full-screen {
    background: #00B14F;
}

.navigation .nav-header>div {
    display: inline-block;
}

.navigation {
    overflow: hidden;
}

.navigation .nav-header {
    padding: 16px 16px 0px 16px;
}

.navigation .nav-body {
    background: #fff;
    padding: 16px;
    box-shadow: 0 0 5px 0 rgb(97 97 97 / 15%);
}

.navigation .nav-header .tabs {
    position: relative;
}

.navigation .nav-header .tabs .tab.active {
    padding: 15px;
    border-top-left-radius: 15px;
    border-top-right-radius: 15px;
    background: #fff;
    display: inline-block;
    position: relative;
    z-index: 2;
    width: 200px;
}

.navigation .nav-header .tabs .tab.active::after {
    content: '';
    width: 115%;
    height: 20px;
    background: #fff;
    display: block;
    position: absolute;
    z-index: 1;
    left: 50%;
    transform: translate(-50%);
}

.navigation .nav-header .tabs .tab.prev, .navigation .nav-header .tabs .tab.next {
    display: inline-block;
    width: 30px;
    height: 30px;
    position: absolute;
    background: #e7f3ff;
    z-index: 10;
    left: -30px;
    bottom: 0;
    border-radius: 50%;
}

.navigation .nav-header .tabs .tab.next {
    right: -30px;
    left: initial;
}

.navigation .nav-body>div {
    display: inline-block;
    padding-left: 30px;
}

.navigation .nav-body .action {
    font-size: 24px;
}

.navigation .nav-body .action .reload {
    font-size: 20px;
}

.navigation .nav-body .action>span {
    margin-right: 9px;
}

.navigation .nav-body .action>.next {
    margin-right: 26px;
}

.navigation .nav-body .search {
    width: 75%;
    margin-left: 10px;
    padding: 10px;
    border-radius: 25px;
    padding-left: 20px;
}

.navigation .nav-body .search .input-search .icon {
    padding-right: 25px;
}

.add-tab {
    z-index: 20;
    position: relative;
    padding-left: 10px;
}

.nav-header .tabs .tab.active span.icon {
    float: right;
}

.action-right .icon {
    padding-left: 15px;
    font-size: 20px;
}

.action-right .icon:first-child {
    padding-left: 10px;
}

.navigation .nav-body>div.action-right {
    padding: initial;
}

.p-16 {
    padding: 24px;
}

.cvo-block {
    background: #fff;
    border-radius: 15px;
    margin-bottom: 20px;
    box-shadow: 0 0 20px 0 rgb(97 97 97 / 15%);
    color:#999999;
}

.cvo-col-5 {
    width: 44%;
    padding: 16px 24px 0 0;
}

.cvo-col-5, .cvo-col-7 {
    float: left;
    vertical-align: top;
}

.cvo-col-7 {
    width: 56%;
    padding: 16px 16px 0 24px;
}


.pl-0 {
    padding-left: 0px;
}

.cvo-block .cvo-block-header {
    padding: 16px;
    border-bottom: 2px solid #eaeaea;
    font-size: 18px;
    font-weight: bold;
    position: relative;
}

.cvo-block .cvo-block-header:after {
    content: '\f142';
    position: absolute;
    right: 16px;
    font-family: 'FontAwesome';
    padding: 5px 12.079px;
    border-radius: 50%;
}

.cvo-block>div, .cvo-block>.block-content {
    padding: 16px;
}

#group-header .h-content {
    background: #fff;
    padding: 16px;
    color: #999999;
    border-radius: 20px;
}

#group-header .h-content .profile-item {
    display: inline-block;
    width: 30%;
    padding-left: 20px;
    padding-right: 40px;
}

#group-header .h-content .cvo-profile-fullname-and-title {
    display: inline-block;
    width: 69%;
    vertical-align: top;
}

#group-header .h-content .profile-item img {
    width: 100%;
    border-radius: 50%;
}

#group-header .h-content .cvo-profile-fullname-and-title #cvo-profile-fullname {
    font-size: 31px;
    text-transform: uppercase;
    font-weight: bold;
    margin-bottom: 8px;
    display: inline-block;
