#cvo-profile-title-wraper {
    margin-bottom: 20px;
}

.information .cvo-profile-info-row {
    width: 46%;
    display: inline-block;
    margin-bottom: 10px;
}

.cvo-profile-address {
    margin-bottom: 10px;
}

.information .cvo-profile-info-row>i {
    padding-right: 10px;
}

.cvo-profile-address>i {
    padding-right: 13px;
