#cv-watermark {
    position: absolute;
    right: 20px;
    bottom: 16px;
    font-size: 12px;
    color: #555;
}

.cvo-section-info>div {
    display: inline-table;
    vertical-align: middle;
}

.cvo-section-info>div:last-child {
    padding: 6px 12px;
    border-radius: 15px;
    float: right;
}

.row {
    margin-bottom: 28px;
}

.cvo-section-info>div:first-child {
    font-weight: 600;
    width: 55%;
}

.cvo-section-info {
    margin-bottom: 15px;
    position: relative;
}

.cvo-experience-wrapper, .cvo-activity-wrapper, .cvo-award-wrapper, .cvo-skill-group-wrapper, .cvo-education-wrapper, .cvo-experience-wrapper {
    margin-bottom: 15px;
    font-weight: 500;
    color: #333;
}

@media print {
    .cvo-document .cvo-page {
        position: initial;
    }

    .cvo-block .row, .cvo-block-header {
        page-break-inside: avoid;
    }

    #cvo-body {
        page-break-after: always;
    }
}

.text-primary {
    color: #0a84ff;
}
.bg-primary {
    background-color: #0a84ff;
}
.bg-primary-trans, .cvo-block .cvo-block-header:after {
    background-color: #E7F3FF;
}
.cvo-section-info > div:last-child {
    background-color: #E7F3FF;
    color: #0a84ff;
}
.cvo-section-info > div:first-child {
    color: #0a84ff;
}

